"use client"

import { useState, useEffect } from "react"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { ScrollArea } from "@/components/ui/scroll-area"
import { FlaskConical, ExternalLink } from "lucide-react"

interface SpaceExperiment {
  id: string
  title: string
  description: string
  agency: string
  category: "biology" | "robotics" | "physics" | "materials" | "other"
  date: string
  imageUrl: string
  learnMoreUrl?: string
}

export function SpaceExperimentsPanel() {
  const [experiments, setExperiments] = useState<SpaceExperiment[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const mockExperiments: SpaceExperiment[] = [

      {
        id: "1",
        title: "Growing Lettuce in Microgravity",
        description: "NASA's Veggie experiment demonstrated how plants can grow without gravity. This helped plan for future deep-space farming.",
        agency: "NASA",
        category: "biology",
        date: "2016-04-12",
        imageUrl: "data:image/jpeg;base64,",
        learnMoreUrl: "https://science.howstuffworks.com/space-lettuce.htm"
      },
      {
        id: "2",
        title: "CIMON – The AI Robot Assistant",
        description: "CIMON is a floating AI assistant helping astronauts with tasks and research aboard the ISS. It uses IBM Watson and facial recognition.",
        agency: "ESA",
        category: "robotics",
        date: "2018-07-02",
        imageUrl: "data:image/jpeg;base64,",
        learnMoreUrl: "https://www.ibm.com/new/announcements/cimon-ai-robot-launches-new-era-space-travel"
      },
      {
        id: "3",
        title: "Bone Density Research in Space",
        description: "Zero-gravity causes rapid bone loss in astronauts. This study helped understand osteoporosis and ways to mitigate bone loss.",
        agency: "JAXA",
        category: "biology",
        date: "2019-10-18",
        imageUrl: "https://spaceinsider.tech/wp-content/uploads/2025/03/Low-Res_image003.jpg",
        learnMoreUrl: "https://www.nasa.gov/missions/station/iss-research/counteracting-bone-and-muscle-loss-in-microgravity/"
      },
      {
        id: "4",
        title: "Crystal Growth in Microgravity",
        description: "Experiments on the ISS show how crystals grow more perfectly in zero gravity, improving drug design.",
        agency: "NASA",
        category: "materials",
        date: "2020-06-30",
        imageUrl: "data:image/jpeg;base64,",
        learnMoreUrl: "https://issnationallab.org/iss360/growing-high-quality-crystals-in-microgravity/"
      },
      {
        id: "5",
        title: "Flame Behavior in Space",
        description: "Studying combustion in space helps scientists understand fire behavior without gravity’s influence.",
        agency: "CSA",
        category: "physics",
        date: "2021-11-19",
        imageUrl: "data:image/jpeg;base64,",
        learnMoreUrl: "https://www.nasa.gov/humans-in-space/fighting-fire-with-fire-new-space-station-experiments-study-flames-in-space/"
      }
    ]


    setExperiments(mockExperiments)
    setLoading(false)
  }, [])

  const getCategoryColor = (category: string) => {
    switch (category) {
      case "biology": return "bg-green-600"
      case "robotics": return "bg-blue-600"
      case "physics": return "bg-purple-600"
      case "materials": return "bg-yellow-600"
      default: return "bg-slate-600"
    }
  }

  if (loading) {
    return (
      <Card className="bg-slate-800/50 border-slate-700 backdrop-blur-sm">
        <CardContent className="p-8 text-center">
          <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-blue-400 mx-auto"></div>
          <p className="text-slate-400 mt-2">Loading experiments...</p>
        </CardContent>
      </Card>
    )
  }

  return (
    <Card className="bg-slate-800/50 border-slate-700 backdrop-blur-sm">
      <CardHeader>
        <CardTitle className="flex items-center gap-2 text-white">
          <FlaskConical className="h-5 w-5 text-blue-400" />
          Space Experiments Logbook
          <Badge variant="secondary" className="bg-green-600 text-white ml-auto">
            {experiments.length} Experiments
          </Badge>
        </CardTitle>
      </CardHeader>

      <CardContent>
        <ScrollArea className="h-96">
          <div className="space-y-4">
            {experiments.map((exp) => (
              <div key={exp.id} className="bg-slate-900/30 rounded-lg p-4 hover:bg-slate-900/50 transition-all duration-200 group">
                <div className="flex gap-4">
                  <img
                    src={exp.imageUrl}
                    alt={exp.title}
                    className="h-20 w-28 object-cover rounded-md border border-slate-700"
                  />
                  <div className="flex-1">
                    <div className="flex justify-between items-start mb-1">
                      <h4 className="text-white font-semibold group-hover:text-blue-400 transition-colors">
                        {exp.title}
                      </h4>
                      {exp.learnMoreUrl && (
                        <Button size="icon" variant="ghost" onClick={() => window.open(exp.learnMoreUrl, "_blank")} className="h-6 w-6">
                          <ExternalLink className="h-4 w-4 text-slate-400" />
                        </Button>
                      )}
                    </div>
                    <p className="text-slate-300 text-sm leading-relaxed mb-2">{exp.description}</p>
                    <div className="flex items-center justify-between text-xs text-slate-400">
                      <span>{exp.agency}</span>
                      <span>{new Date(exp.date).toLocaleDateString()}</span>
                      <Badge className={`${getCategoryColor(exp.category)} text-white capitalize`}>{exp.category}</Badge>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </ScrollArea>
      </CardContent>
    </Card>
  )
}
